public class SteuerIdValidator {
    public static boolean validate(String id) {
        if (id == null || !id.matches("[1-9]\\d{10}")) {
            return false;
        }
        int[] counts = new int[10];
        for (int i = 0; i < 10; i++) {
            counts[Character.getNumericValue(id.charAt(i))]++;
        }
        int doubleCount = 0, tripleCount = 0;
        for (int count : counts) {
            if (count == 2) doubleCount++;
            if (count == 3) tripleCount++;
        }
        if (!((doubleCount == 1 && tripleCount == 0) || (doubleCount == 0 && tripleCount == 1))) {
            return false;
        }
        int r = 10;
        for (int i = 0; i < 10; i++) {
            int s = (r + Character.getNumericValue(id.charAt(i))) % 10;
            if (s == 0) s = 10;
            r = (s * 2) % 11;
        }
        int checksum = (11 - r) % 10;
        return checksum == Character.getNumericValue(id.charAt(10));
    }
}

