package main

import (
	"regexp"
	"strconv"
)

func ValidateSteuerID(id string) bool {
	if matched, _ := regexp.MatchString(`^[1-9]\d{10}$`, id); !matched {
		return false
	}
	counts := make(map[rune]int)
	for _, char := range id[:10] {
		counts[char]++
	}
	doubleCount, tripleCount := 0, 0
	for _, count := range counts {
		if count == 2 {
			doubleCount++
		} else if count == 3 {
			tripleCount++
		}
	}
	if !((doubleCount == 1 && tripleCount == 0) || (doubleCount == 0 && tripleCount == 1)) {
		return false
	}
	r := 10
	for i := 0; i < 10; i++ {
		digit, _ := strconv.Atoi(string(id[i]))
		s := (r + digit) % 10
		if s == 0 {
			s = 10
		}
		r = (s * 2) % 11
	}
	checksum := (11 - r) % 10
	lastDigit, _ := strconv.Atoi(string(id[10]))
	return checksum == lastDigit
}

