pub fn validate_steuer_id(id: &str) -> bool {
    if id.len() != 11 || !id.chars().all(|c| c.is_ascii_digit()) || id.starts_with('0') {
        return false;
    }
    let mut counts = [0; 10];
    for char in id.chars().take(10) {
        counts[char.to_digit(10).unwrap() as usize] += 1;
    }
    let double_count = counts.iter().filter(|&&c| c == 2).count();
    let triple_count = counts.iter().filter(|&&c| c == 3).count();
    if !((double_count == 1 && triple_count == 0) || (double_count == 0 && triple_count == 1)) {
        return false;
    }
    let digits: Vec<u32> = id.chars().map(|c| c.to_digit(10).unwrap()).collect();
    let mut r = 10;
    for i in 0..10 {
        let mut s = (r + digits[i]) % 10;
        if s == 0 { s = 10; }
        r = (s * 2) % 11;
    }
    let checksum = (11 - r) % 10;
    checksum == digits[10]
}
